mapper.update:
UPDATE MEMBER_INFO /* adminMapper.changeRoleUser (운영자에서 사용자로 변경)*/
   SET USER_ROLE = 'USER';
 WHERE MEMBER_Id = #{memberId}

UPDATE MEMBER_INFO /* adminMapper.changeRoleAdmin (사용자에서 운영자로 변경) */
   SET USER_ROLE = 'ADMIN'
 WHERE MEMBER_ID = #{memberId}

UPDATE MEMBER_INFO /*AdminMapper.writeNotUser (USER_STATUS 값을 N으로 변경 글 작성 불가)  */
   SET USER_STATUS ='N'
 where MEMBER_ID  = #{memberId}

UPDATE member_info /*(AdminMapper.writeUser.USER_STATUS (값을 Y로 변경 글 작성 가능) */
   SET USER_STATUS = 'Y'
 WHERE MEMBER_ID = #{memberId}
